// 1. Read existing headlines and URLs already stored in Cloudflare D1
const existingTitles = [];
const existingUrls = new Set();
try {
  const d1Res = $('Get Existing D1 Headlines').first()?.json;
  if (d1Res && Array.isArray(d1Res.data)) {
    for (const item of d1Res.data) {
      if (item.title) existingTitles.push(item.title);
      if (item.source_url) existingUrls.add(item.source_url.trim());
    }
  }
} catch (e) {}

const MAX_DAYS = 7;
const cutoffTime = Date.now() - (MAX_DAYS * 24 * 60 * 60 * 1000);

function cleanTitleText(t) {
  let text = (t || '').trim();
  if (text.includes(' - ')) {
    const parts = text.split(' - ');
    parts.pop();
    text = parts.join(' - ').trim();
  }
  if (text.includes(' | ')) {
    const parts = text.split(' | ');
    parts.pop();
    text = parts.join(' | ').trim();
  }
  return text;
}

function normalize(t) {
  return cleanTitleText(t)
    .toLowerCase()
    .replace(/[^a-z0-9]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const stopWords = new Set([
  'a', 'about', 'above', 'after', 'again', 'against', 'all', 'am', 'an', 'and',
  'any', 'are', 'as', 'at', 'be', 'because', 'been', 'before', 'being', 'below',
  'between', 'both', 'but', 'by', 'can', 'could', 'did', 'do', 'does', 'doing',
  'down', 'during', 'each', 'few', 'for', 'from', 'further', 'had', 'has', 'have',
  'having', 'he', 'her', 'here', 'how', 'i', 'if', 'in', 'into', 'is', 'it',
  'its', 'just', 'more', 'most', 'must', 'my', 'no', 'nor', 'not', 'now', 'of',
  'off', 'on', 'once', 'only', 'or', 'other', 'our', 'out', 'over', 'own', 'same',
  'she', 'should', 'so', 'some', 'such', 'than', 'that', 'the', 'their', 'theirs',
  'them', 'then', 'there', 'these', 'they', 'this', 'those', 'through', 'to',
  'too', 'under', 'until', 'up', 'very', 'was', 'we', 'were', 'what', 'when',
  'where', 'which', 'while', 'who', 'whom', 'why', 'will', 'with', 'you', 'your'
]);

function extractWords(text) {
  return new Set(
    cleanTitleText(text)
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, ' ')
      .split(/\s+/)
      .filter(w => w.length >= 3 && !stopWords.has(w))
  );
}

function isSimilar(titleA, titleB) {
  const normA = normalize(titleA);
  const normB = normalize(titleB);
  if (!normA || !normB) return false;
  if (normA === normB) return true;
  if (normA.length > 15 && normB.length > 15) {
    if (normA.startsWith(normB) || normB.startsWith(normA)) return true;
    if (normA.includes(normB) || normB.includes(normA)) return true;
  }
  const a = extractWords(titleA);
  const b = extractWords(titleB);
  if (a.size === 0 || b.size === 0) return false;
  let common = 0;
  for (const w of a) {
    if (b.has(w)) common++;
  }
  const minSize = Math.min(a.size, b.size);
  if (common >= 3 && (common / minSize) >= 0.5) return true;
  if (common >= 4) return true;
  return (common / minSize) >= 0.6;
}

const incomingItems = $input.all();
const newItemsToScrape = [];
const seenBatchUrls = new Set();
const seenBatchTitles = [];

for (const item of incomingItems) {
  const raw = item.json;
  const rawDate = raw.pubDate || raw.isoDate || raw.published;
  const pubTime = rawDate ? new Date(rawDate).getTime() : Date.now();
  if (isNaN(pubTime) || pubTime < cutoffTime) continue;

  const googleUrl = (raw.link || raw.guid || '').trim();
  if (!googleUrl || seenBatchUrls.has(googleUrl) || existingUrls.has(googleUrl)) continue;

  let title = (raw.title || '').trim();
  let source = 'Industry News';
  if (title.includes(' - ')) {
    const parts = title.split(' - ');
    const src = parts.pop().trim();
    title = parts.join(' - ').trim();
    if (src) source = src;
  } else if (title.includes(' | ')) {
    const parts = title.split(' | ');
    const src = parts.pop().trim();
    title = parts.join(' | ').trim();
    if (src) source = src;
  }
  if (raw.source) {
    if (typeof raw.source === 'string') {
      source = raw.source;
    } else if (typeof raw.source === 'object') {
      source = raw.source._ || raw.source.name || raw.source['#text'] || source;
    }
  }

  // Deduplicate against existing D1 titles
  let isDup = false;
  for (const existingTitle of existingTitles) {
    if (isSimilar(title, existingTitle)) {
      isDup = true;
      break;
    }
  }
  if (isDup) continue;

  // Deduplicate within this batch
  for (const batchTitle of seenBatchTitles) {
    if (isSimilar(title, batchTitle)) {
      isDup = true;
      break;
    }
  }
  if (isDup) continue;

  seenBatchUrls.add(googleUrl);
  seenBatchTitles.push(title);

  newItemsToScrape.push({
    json: {
      title,
      source,
      googleUrl,
      published_at: new Date(pubTime).toISOString(),
      rawDescription: raw.description || ''
    }
  });
}

return newItemsToScrape;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const html = typeof item.data === 'string' ? item.data : (item.body || JSON.stringify(item));

  let article = {};
  try {
    article = $('Filter & Deduplicate New Items').all()[i]?.json || {};
  } catch (e) {
    article = item;
  }

  const idMatch = html.match(/data-n-a-id="([^"]+)"/);
  const tsMatch = html.match(/data-n-a-ts="([^"]+)"/);
  const sgMatch = html.match(/data-n-a-sg="([^"]+)"/);

  if (idMatch && tsMatch && sgMatch) {
    const id = idMatch[1];
    const ts = tsMatch[1];
    const sg = sgMatch[1];

    const innerPayload = JSON.stringify([
      'garturlreq',
      [
        ['en-IN', 'IN', ['FINANCE_TOP_INDICES', 'GENESIS_PUBLISHER_SECTION', 'WEB_TEST_1_0_0'], null, null, 1, 1, 'IN:en', null, null, null, null, null, null, null, false, 5],
        'en-IN', 'IN', true, [3, 5, 9, 18], 1, true, '1022455856', false, false, null, false
      ],
      id,
      parseInt(ts, 10),
      sg
    ]);

    const batchPayload = 'f.req=' + encodeURIComponent(JSON.stringify([[
      ['Fbv4je', innerPayload, null, 'generic']
    ]]));

    results.push({
      json: {
        ...article,
        hasTokens: true,
        batchPayload
      }
    });
  } else {
    results.push({
      json: {
        ...article,
        hasTokens: false,
        decodedUrl: article.googleUrl
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const resText = typeof item.data === 'string' ? item.data : (item.body || JSON.stringify(item));

  let article = {};
  try {
    article = $('Extract Google Tokens').all()[i]?.json || {};
  } catch (e) {
    article = item;
  }

  const urls = resText.match(/https?:\/\/[^\\\"\s]+/g) || [];
  const publisherUrls = urls.filter(u => !u.includes('google.com') && !u.includes('gstatic.com'));
  const decodedUrl = publisherUrls[0] || article.googleUrl || article.decodedUrl;

  results.push({
    json: {
      ...article,
      decodedUrl
    }
  });
}

return results;

const items = $input.all();
const results = [];

const DIVERSE_IMAGES = ["https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1601584115197-04ecc0da31d7?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1559136555-9303baea8ebd?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1570710891163-6d3b5c47248b?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1518241353330-0f7941c2d9b5?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1553413077-190dd305871c?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1592838064575-70ed626d3a0e?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1541427468627-a89a96e5ca1d?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1577717903315-1691ae25ab3f?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1569154941061-e231b4725ef1?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1524522173746-f628baad3644?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1580674285054-bed31e145f59?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1494412574643-ff11b0a5c1c3?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1587293852726-70cdb56c2866?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1505705694340-019e1e335916?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1436491865332-7a61a109cc05?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1521791136064-7986c2920216?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1586528116493-a029325540fa?auto=format&fit=crop&w=1200&q=80"];

function cleanHtml(str) {
  if (!str) return '';
  return str
    .replace(/<[^>]*>?/gm, ' ')
    .replace(/&quot;/g, '\"')
    .replace(/&#39;|&apos;|&#8217;|&#8216;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&hellip;|&#8230;/g, '...')
    .replace(/&mdash;|&#8212;/g, ' — ')
    .replace(/&ndash;|&#8211;/g, ' – ')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const html = typeof item.data === 'string' ? item.data : (item.body || '');

  let article = {};
  try {
    article = $('Parse Real Publisher URL').all()[i]?.json || {};
  } catch (e) {
    article = item;
  }

  const title = article.title;
  const source = article.source || 'Industry Source';
  const directUrl = article.decodedUrl || article.googleUrl;
  const publishedAt = article.published_at || new Date().toISOString();

  // 1. Extract Real OpenGraph Image
  let imageUrl = null;
  const imgMatch = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i) ||
                   html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
  if (imgMatch && imgMatch[1]) {
    const found = imgMatch[1].trim();
    if (found.startsWith('http') && !found.includes('1x1') && !found.endsWith('.ico') && !found.includes('favicon')) {
      imageUrl = found;
    }
  }

  // 2. Extract Real OpenGraph Description
  let description = null;
  const descMatch = html.match(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']+)["']/i) ||
                    html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:description["']/i);
  if (descMatch && descMatch[1]) {
    const cleanDesc = cleanHtml(descMatch[1]);
    if (cleanDesc.length > 40 && !cleanDesc.toLowerCase().includes('enable javascript')) {
      description = cleanDesc;
    }
  }

  // 3. Sector Classification
  const combined = (title + ' ' + (description || '')).toLowerCase();
  let category = 'Logistics';
  let contentType = 'news';

  if (/(shipping|ocean freight|vessels?|maritime|ports?|terminals?|berths?|container ship|dry bulk|tankers?|red sea|suez|boxship)/.test(combined)) {
    category = 'Shipping';
  } else {
    category = 'Logistics';
  }

  if (/(surge|plunge|soar|record high|forecast|outlook|inflation|growth rate|freight index|spot rate|downturn|quarterly report|earnings|q1|q2|q3|q4)/.test(combined)) {
    contentType = 'trend';
  }

  // 4. Image Fallback Guard
  if (!imageUrl) {
    let hash = 0;
    for (let j = 0; j < title.length; j++) {
      hash = ((hash << 5) - hash) + title.charCodeAt(j);
      hash |= 0;
    }
    imageUrl = DIVERSE_IMAGES[Math.abs(hash) % DIVERSE_IMAGES.length];
  }

  // 5. Description Fallback Guard
  if (!description || description.length < 50) {
    description = `${title}. Direct industry update reported via ${source}. Coverage tracks ongoing operational developments, freight distribution dynamics, and strategic market updates across regional and global transport corridors.`;
  }

  results.push({
    json: {
      title,
      description,
      source,
      source_url: directUrl,
      image_url: imageUrl,
      category,
      published_at: publishedAt,
      content_type: contentType
    }
  });
}

return results;

const items = $input.all();
let inserted = 0;
let duplicates = 0;
let errors = 0;

for (const item of items) {
  const j = item.json;
  const statusCode = j.statusCode || j.status || 0;
  if (statusCode === 201 || (j.id && !j.duplicate)) {
    inserted++;
  } else if (statusCode === 409 || j.duplicate || j.status === 'duplicate_skipped') {
    duplicates++;
  } else {
    errors++;
  }
}

return [{
  json: {
    execution_time: new Date().toISOString(),
    total_processed: items.length,
    newly_inserted: inserted,
    duplicates_skipped: duplicates,
    errors: errors,
    pipeline: 'Linear Google News URL Decoder & Publisher OpenGraph Scraper',
    status: errors === 0 ? 'success' : 'completed'
  }
}];
